{
  "findings": [
    {
      "check_id": "CKV_AZURE_114",
      "title": "Key Vault secret missing content_type",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The secret resource does not specify a content_type, which is recommended to ensure proper handling and validation of the secret value by consumers and Azure services."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  content_type = \"text/plain\"\n  depends_on   = [azurerm_mssql_database.legal_metadata_db]\n}",
  "fix_summary": "Added the 'content_type' attribute set to 'text/plain' to the azurerm_key_vault_secret resource to comply with security best practices for secret metadata."
}
